from pathlib import Path
import re

ROOT = Path(__file__).resolve().parent
strategy_path = ROOT / "src" / "mexc_tick_scalper" / "hybrid_strategy.py"
tests_path = ROOT / "tests" / "test_hybrid_strategy.py"

strategy = strategy_path.read_text(encoding="utf-8")
tests = tests_path.read_text(encoding="utf-8")

NEW_CLASS = '@dataclass(slots=True)\nclass AsymmetricExitPolicy:\n    """Fast loss cutting with staged executable-price trailing protection."""\n\n    side: int\n    entry_price: float\n    early_adverse_changes: int = 2\n    liq_buffer_fraction: float = 0.25\n    winner_arm_bps: float = 0.5\n    winner_pullback_bps: float = 1.5\n    winner_flip_pullback_bps: float = 0.5\n    flip_confidence: float = 0.30\n    fade_confidence: float = 0.12\n    min_hold_seconds: float = 0.35\n    winner_flip_confirmations: int = 3\n    hard_trailing_multiplier: float = 2.0\n    micro_lock_activation_bps: float = 3.0\n    micro_lock_profit_bps: float = 0.5\n    strong_lock_activation_bps: float = 5.0\n    strong_lock_profit_bps: float = 2.0\n    trailing_activation_bps: float = 6.0\n    trailing_distance_bps: float | None = None\n    last_price: float | None = None\n    extreme_price: float | None = None\n    adverse_count: int = 0\n    winner_armed: bool = False\n    winner_opposite_count: int = 0\n    peak_signed_bps: float = 0.0\n    trailing_stop_bps: float | None = None\n\n    def __post_init__(self) -> None:\n        if self.side not in (1, -1):\n            raise ValueError("side must be +1 or -1")\n        if self.entry_price <= 0:\n            raise ValueError("entry_price must be positive")\n        if self.early_adverse_changes < 1:\n            raise ValueError("early_adverse_changes must be >= 1")\n        if self.winner_flip_confirmations < 1:\n            raise ValueError("winner_flip_confirmations must be >= 1")\n        if self.winner_flip_pullback_bps < 0:\n            raise ValueError("winner_flip_pullback_bps must be >= 0")\n        if self.hard_trailing_multiplier < 1:\n            raise ValueError("hard_trailing_multiplier must be >= 1")\n        if self.micro_lock_activation_bps <= 0:\n            raise ValueError("micro_lock_activation_bps must be positive")\n        if self.micro_lock_profit_bps < 0:\n            raise ValueError("micro_lock_profit_bps must be >= 0")\n        if self.strong_lock_activation_bps < self.micro_lock_activation_bps:\n            raise ValueError("strong_lock_activation_bps must be >= micro_lock_activation_bps")\n        if self.strong_lock_profit_bps < self.micro_lock_profit_bps:\n            raise ValueError("strong_lock_profit_bps must be >= micro_lock_profit_bps")\n        if self.trailing_activation_bps < self.strong_lock_activation_bps:\n            raise ValueError("trailing_activation_bps must be >= strong_lock_activation_bps")\n        if self.trailing_distance_bps is not None and self.trailing_distance_bps <= 0:\n            raise ValueError("trailing_distance_bps must be positive when set")\n        if not 0 < self.liq_buffer_fraction < 1:\n            raise ValueError("liq_buffer_fraction must be between 0 and 1")\n        self.last_price = self.entry_price\n        self.extreme_price = self.entry_price\n\n    def _near_liquidation(self, price: float, liquidation_price: float | None) -> bool:\n        if liquidation_price is None or liquidation_price <= 0:\n            return False\n        if self.side == 1 and liquidation_price < self.entry_price:\n            trigger = liquidation_price + (self.entry_price - liquidation_price) * self.liq_buffer_fraction\n            return price <= trigger\n        if self.side == -1 and liquidation_price > self.entry_price:\n            trigger = liquidation_price - (liquidation_price - self.entry_price) * self.liq_buffer_fraction\n            return price >= trigger\n        return False\n\n    def _signed_return_bps(self, price: float) -> float:\n        return self.side * (price - self.entry_price) / self.entry_price * 10_000.0\n\n    def _pullback_bps(self, price: float) -> float:\n        assert self.extreme_price is not None\n        if self.side == 1:\n            return max(0.0, (self.extreme_price - price) / self.extreme_price * 10_000.0)\n        return max(0.0, (price - self.extreme_price) / self.extreme_price * 10_000.0)\n\n    def _update_trailing_stop(self) -> None:\n        candidate: float | None = None\n        if self.peak_signed_bps >= self.micro_lock_activation_bps:\n            candidate = self.micro_lock_profit_bps\n        if self.peak_signed_bps >= self.strong_lock_activation_bps:\n            candidate = max(candidate or 0.0, self.strong_lock_profit_bps)\n        if self.peak_signed_bps >= self.trailing_activation_bps:\n            distance = self.trailing_distance_bps if self.trailing_distance_bps is not None else self.winner_pullback_bps\n            candidate = max(candidate or 0.0, self.peak_signed_bps - distance)\n        if candidate is None:\n            return\n        if self.trailing_stop_bps is None:\n            self.trailing_stop_bps = candidate\n        else:\n            self.trailing_stop_bps = max(self.trailing_stop_bps, candidate)\n\n    def on_tick(\n        self,\n        *,\n        price: float,\n        liquidation_price: float | None,\n        signal: MicrostructureSnapshot,\n        age_seconds: float,\n        signal_fresh: bool = True,\n    ) -> str | None:\n        if price <= 0:\n            return None\n        if self._near_liquidation(price, liquidation_price):\n            return "liquidation_guard"\n        assert self.last_price is not None\n        assert self.extreme_price is not None\n\n        signed_bps = self._signed_return_bps(price)\n        self.peak_signed_bps = max(self.peak_signed_bps, signed_bps)\n        self._update_trailing_stop()\n        if signed_bps >= self.winner_arm_bps:\n            self.winner_armed = True\n\n        made_new_favorable_extreme = (\n            (self.side == 1 and price > self.extreme_price)\n            or (self.side == -1 and price < self.extreme_price)\n        )\n        if made_new_favorable_extreme:\n            self.extreme_price = price\n            self.winner_opposite_count = 0\n\n        if price != self.last_price:\n            delta = price - self.last_price\n            favorable = delta > 0 if self.side == 1 else delta < 0\n            if favorable:\n                self.adverse_count = 0\n            elif not self.winner_armed:\n                self.adverse_count += 1\n            self.last_price = price\n\n        opposite = signal.direction == -self.side and signal.confidence >= self.flip_confidence\n        supportive = signal.direction == self.side and signal.confidence >= self.fade_confidence\n\n        if not self.winner_armed:\n            if signal_fresh and age_seconds >= self.min_hold_seconds and opposite:\n                return "early_signal_flip"\n            if self.adverse_count >= self.early_adverse_changes:\n                return "early_adverse_cut"\n            return None\n\n        if self.trailing_stop_bps is not None and signed_bps <= self.trailing_stop_bps:\n            return "winner_staged_trailing_stop"\n\n        if signal_fresh:\n            if opposite and not made_new_favorable_extreme:\n                self.winner_opposite_count += 1\n            elif not opposite:\n                self.winner_opposite_count = 0\n\n        pullback_bps = self._pullback_bps(price)\n        if (\n            signal_fresh\n            and age_seconds >= self.min_hold_seconds\n            and self.winner_opposite_count >= self.winner_flip_confirmations\n            and pullback_bps >= self.winner_flip_pullback_bps\n        ):\n            return "winner_signal_flip_price_confirmed"\n        if signal_fresh and pullback_bps >= self.winner_pullback_bps and not supportive:\n            return "winner_pullback_fade"\n        if not signal_fresh:\n            hard_trailing_bps = self.winner_pullback_bps * self.hard_trailing_multiplier\n            if pullback_bps >= hard_trailing_bps:\n                return "winner_price_trailing_stop"\n        return None\n'
TEST_BLOCK = 'def test_staged_stop_locks_microprofit_from_three_bps():\n    policy = AsymmetricExitPolicy(side=1, entry_price=100.0, winner_arm_bps=1.0, winner_pullback_bps=1.5)\n    assert policy.on_tick(price=100.030, liquidation_price=None, signal=_snap(1, 0.7), age_seconds=1.0) is None\n    assert policy.trailing_stop_bps == 0.5\n    assert policy.on_tick(price=100.004, liquidation_price=None, signal=_snap(1, 0.8), age_seconds=1.2) == "winner_staged_trailing_stop"\n\n\ndef test_staged_stop_raises_floor_at_five_bps():\n    policy = AsymmetricExitPolicy(side=1, entry_price=100.0, winner_arm_bps=1.0, winner_pullback_bps=1.5)\n    assert policy.on_tick(price=100.050, liquidation_price=None, signal=_snap(1, 0.7), age_seconds=1.0) is None\n    assert policy.trailing_stop_bps == 2.0\n    assert policy.on_tick(price=100.019, liquidation_price=None, signal=_snap(1, 0.8), age_seconds=1.2) == "winner_staged_trailing_stop"\n\n\ndef test_mature_long_switches_to_ratcheting_trailing():\n    policy = AsymmetricExitPolicy(side=1, entry_price=100.0, winner_arm_bps=1.0, winner_pullback_bps=1.5)\n    assert policy.on_tick(price=100.060, liquidation_price=None, signal=_snap(1, 0.7), age_seconds=1.0) is None\n    assert policy.trailing_stop_bps is not None and 4.49 <= policy.trailing_stop_bps <= 4.51\n    assert policy.on_tick(price=100.080, liquidation_price=None, signal=_snap(1, 0.8), age_seconds=1.2) is None\n    assert policy.trailing_stop_bps is not None and 6.49 <= policy.trailing_stop_bps <= 6.51\n    assert policy.on_tick(price=100.064, liquidation_price=None, signal=_snap(1, 0.8), age_seconds=1.3) == "winner_staged_trailing_stop"\n\n\ndef test_mature_short_uses_symmetric_staged_trailing():\n    policy = AsymmetricExitPolicy(side=-1, entry_price=100.0, winner_arm_bps=1.0, winner_pullback_bps=1.5)\n    assert policy.on_tick(price=99.940, liquidation_price=None, signal=_snap(-1, 0.7), age_seconds=1.0) is None\n    assert policy.trailing_stop_bps is not None and 4.49 <= policy.trailing_stop_bps <= 4.51\n    assert policy.on_tick(price=99.920, liquidation_price=None, signal=_snap(-1, 0.8), age_seconds=1.2) is None\n    assert policy.trailing_stop_bps is not None and 6.49 <= policy.trailing_stop_bps <= 6.51\n    assert policy.on_tick(price=99.936, liquidation_price=None, signal=_snap(-1, 0.8), age_seconds=1.3) == "winner_staged_trailing_stop"\n\n\ndef test_stop_never_moves_backwards():\n    policy = AsymmetricExitPolicy(side=1, entry_price=100.0, winner_arm_bps=1.0, winner_pullback_bps=1.5)\n    assert policy.on_tick(price=100.060, liquidation_price=None, signal=_snap(1, 0.7), age_seconds=1.0) is None\n    first = policy.trailing_stop_bps\n    assert first is not None\n    assert policy.on_tick(price=100.080, liquidation_price=None, signal=_snap(1, 0.7), age_seconds=1.1) is None\n    second = policy.trailing_stop_bps\n    assert second is not None and second > first\n    assert policy.on_tick(price=100.075, liquidation_price=None, signal=_snap(1, 0.7), age_seconds=1.2) is None\n    assert policy.trailing_stop_bps == second\n'

pattern = re.compile(
    r"@dataclass\(slots=True\)\s*\r?\nclass AsymmetricExitPolicy:.*?(?=\r?\n\r?\nHoldUntilAgainstExit = AsymmetricExitPolicy)",
    re.DOTALL,
)
matches = list(pattern.finditer(strategy))
if len(matches) != 1:
    raise SystemExit(f"STOP: expected exactly one AsymmetricExitPolicy class, found {len(matches)}; no files were written")
strategy_new = pattern.sub(NEW_CLASS, strategy, count=1)

names = [
    "test_staged_stop_locks_microprofit_from_three_bps",
    "test_staged_stop_raises_floor_at_five_bps",
    "test_mature_long_switches_to_ratcheting_trailing",
    "test_mature_short_uses_symmetric_staged_trailing",
    "test_stop_never_moves_backwards",
]
tests_new = tests
for name in names:
    tests_new = re.sub(
        rf"\r?\n*def {name}\(\):.*?(?=\r?\n\r?\ndef |\Z)",
        "",
        tests_new,
        flags=re.DOTALL,
    )

marker_re = re.compile(r"^def test_winner_pullback_requires_signal_fade\(\):", re.MULTILINE)
if not marker_re.search(tests_new):
    raise SystemExit("STOP: test insertion point not found; no files were written")
tests_new = marker_re.sub(TEST_BLOCK + "\n\n\ndef test_winner_pullback_requires_signal_fade():", tests_new, count=1)

compile(strategy_new, str(strategy_path), "exec")
compile(tests_new, str(tests_path), "exec")

strategy_path.write_text(strategy_new, encoding="utf-8")
tests_path.write_text(tests_new, encoding="utf-8")

print("OK: staged trailing-stop applied")
print("MFE >= 3 bps -> stop +0.5 bps")
print("MFE >= 5 bps -> stop +2.0 bps")
print("MFE >= 6 bps -> ratcheting stop = peak - winner_pullback_bps")
print("Stop never moves backward")
